        this.elements[1] *= scale.x;
        this.elements[2] *= scale.x;
        this.elements[4] *= scale.y;
        this.elements[5] *= scale.y;
        this.elements[6] *= scale.y;
        this.elements[8] *= scale.z;
        this.elements[9] *= scale.z;
        this.elements[10] *= scale.z;
