        this.elements[1] = xy + wz;
        this.elements[2] = xz - wy;
        this.elements[3] = 0;
        this.elements[4] = xy - wz;
        this.elements[5] = 1 - (xx + zz);
        this.elements[6] = yz + wx;
        this.elements[7] = 0;
        this.elements[8] = xz + wy;
        this.elements[9] = yz - wx;
        this.elements[10] = 1 - (xx + yy);
        this.elements[11] = 0;
