// ==================== MINI-GRAPH ====================
class MiniGraph {
    constructor(name, fg, bg) {
        this._min = Infinity;
        this._max = 0;
        this._name = name;
        this._fg = fg;
        this._bg = bg;
        this._dpr = Math.min(window.devicePixelRatio || 1, 2);
        const W = MiniGraph._W;
        const H = MiniGraph._H;
        const c = document.createElement("canvas");
        c.width = W * this._dpr;
        c.height = H * this._dpr;
        c.style.cssText = `width:${W}px;height:${H}px;display:block`;
        const ctx = c.getContext("2d");
        ctx.scale(this._dpr, this._dpr);
        ctx.fillStyle = bg;
        ctx.fillRect(0, 0, W, H);
        ctx.fillStyle = fg;
        ctx.font = "bold 9px monospace";
        ctx.textBaseline = "top";
        ctx.fillText(name, 3, 2);
        this.canvas = c;
        this._ctx = ctx;
    }
    update(value, maxScale) {
        if (value < this._min)
            this._min = value;
        if (value > this._max)
            this._max = value;
        const ctx = this._ctx;
        const W = MiniGraph._W;
        const TH = MiniGraph._TH;
        const GH = MiniGraph._GH;
        const dpr = this._dpr;
        ctx.fillStyle = this._bg;
        ctx.fillRect(0, 0, W, TH);
        ctx.fillStyle = this._fg;
        ctx.font = "bold 9px monospace";
        ctx.textBaseline = "top";
        ctx.fillText(`${Math.round(value)} ${this._name} (${Math.round(this._min)}-${Math.round(this._max)})`, 3, 2);
        ctx.drawImage(this.canvas, 1 * dpr, TH * dpr, (W - 1) * dpr, GH * dpr, 0, TH, W - 1, GH);
        ctx.fillStyle = this._bg;
        ctx.fillRect(W - 1, TH, 1, GH);
        const barH = Math.round(Math.min(value / maxScale, 1) * GH);
        if (barH > 0) {
            ctx.fillStyle = this._fg;
            ctx.fillRect(W - 1, TH + GH - barH, 1, barH);
        }
    }
    reset() {
        this._min = Infinity;
        this._max = 0;
    }
}
